/**
 * Parse ClozeQuestionSource modules and emit ClozeQuestionIR as `clozeQuestions.ts`.
 *
 * Optional codegen: the app normally imports `clozeSource.ts` and parses at runtime.
 * Use this when you want committed `clozeQuestions.ts` IR (CI checks, no parser in bundle).
 *
 * Convention:
 *   - Author `clozeSource.ts` next to page data (like `questions.ts`).
 *   - Export `clozeQuestionSources: ClozeQuestionSource[]`, or individual source objects.
 *   - Output: sibling `clozeQuestions.ts` (generated; do not edit).
 *
 * Run:
 *   npm run build:cloze
 *   deno task build-cloze
 */

import { readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

import type {
    ClozeQuestionIR,
    ClozeQuestionSource,
} from "$lib/common/QuestionTypes/ClozeQuestion/v1/clozeQuestion.ts";
import {
    ClozeParseError,
    parseClozeQuestion,
} from "$lib/common/QuestionTypes/ClozeQuestion/v1/parser.ts";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const routesExpRoot = join(repoRoot, "src", "routes", "exp");
const SOURCE_FILENAME = "clozeSource.ts";
const OUTPUT_FILENAME = "clozeQuestions.ts";

function walkClozeSourceFiles(dir: string): string[] {
    const found: string[] = [];
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
        const path = join(dir, entry.name);
        if (entry.isDirectory()) {
            found.push(...walkClozeSourceFiles(path));
        } else if (entry.isFile() && entry.name === SOURCE_FILENAME) {
            found.push(path);
        }
    }
    return found;
}

function toExpImportSpecifier(sourceFilePath: string): string {
    const rel = relative(routesExpRoot, sourceFilePath).replaceAll("\\", "/");
    return `$exp/${rel}`;
}

function isClozeQuestionSource(value: unknown): value is ClozeQuestionSource {
    if (typeof value !== "object" || value === null) {
        return false;
    }
    const record = value as Record<string, unknown>;
    if (typeof record.qid !== "string" || typeof record.label !== "string") {
        return false;
    }
    const { content } = record;
    if (typeof content === "string") {
        return true;
    }
    return (
        Array.isArray(content)
        && content.length > 0
        && content.every((line) => typeof line === "string")
    );
}

function collectSources(moduleExports: Record<string, unknown>): ClozeQuestionSource[] {
    const named = moduleExports.clozeQuestionSources;
    if (Array.isArray(named)) {
        for (const entry of named) {
            if (!isClozeQuestionSource(entry)) {
                throw new Error(
                    "clozeQuestionSources must contain only ClozeQuestionSource objects",
                );
            }
        }
        return named;
    }

    const sources: ClozeQuestionSource[] = [];
    for (const value of Object.values(moduleExports)) {
        if (isClozeQuestionSource(value)) {
            sources.push(value);
        }
    }
    if (sources.length === 0) {
        throw new Error(
            "Expected export clozeQuestionSources: ClozeQuestionSource[] or ClozeQuestionSource objects",
        );
    }
    return sources;
}

function formatGeneratedFile(questions: ClozeQuestionIR[]): string {
    const body = JSON.stringify(questions, null, 4);
    return [
        "// Generated by scripts/build-cloze-questions.ts. Do not edit manually.",
        "",
        'import type { ClozeQuestionIR } from "$lib/common/QuestionTypes/ClozeQuestion/v1/clozeQuestion.ts";',
        "",
        `export const clozeQuestions: ClozeQuestionIR[] = ${body};`,
        "",
    ].join("\n");
}

async function buildOne(sourceFilePath: string): Promise<void> {
    const importSpec = toExpImportSpecifier(sourceFilePath);
    let moduleExports: Record<string, unknown>;
    try {
        moduleExports = (await import(importSpec)) as Record<string, unknown>;
    } catch (err) {
        throw new Error(`Failed to import ${importSpec}: ${err}`);
    }

    const sources = collectSources(moduleExports);
    const questions: ClozeQuestionIR[] = [];
    for (const source of sources) {
        try {
            questions.push(parseClozeQuestion(source));
        } catch (err) {
            if (err instanceof ClozeParseError) {
                throw new Error(`${sourceFilePath}: ${err.message}`);
            }
            throw err;
        }
    }

    const outPath = join(dirname(sourceFilePath), OUTPUT_FILENAME);
    writeFileSync(outPath, formatGeneratedFile(questions), "utf8");
    console.log(`Wrote ${relative(repoRoot, outPath)} (${questions.length} question(s))`);
}

async function main(): Promise<void> {
    if (!statSync(routesExpRoot, { throwIfNoEntry: false })?.isDirectory()) {
        console.log("No src/routes/exp directory; nothing to generate.");
        return;
    }

    const sourceFiles = walkClozeSourceFiles(routesExpRoot);
    if (sourceFiles.length === 0) {
        console.log(`No ${SOURCE_FILENAME} files under src/routes/exp.`);
        return;
    }

    for (const path of sourceFiles.sort()) {
        await buildOne(path);
    }
}

await main();
